[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableModuleMarkupGroupId extends UPSPricingAttributeInventTableModule implements UPSIPricingAttribute
