public str getName()
{
    return fieldPName(InventTableModule, MarkupGroupId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);

    MarkupGroup   markupGroup;

    while select GroupId from markupGroup
    {
        if (!ret.in(markupGroup.GroupId))
        {
            ret.add(markupGroup.GroupId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTableModule, MarkupGroupId));
    qbr.value(queryValue(_value));
}
